import {expect,test} from 'bun:test';
import {isReviewedFalsePositive} from '../filter-secret-findings.mjs';

test('secret exceptions require exact fixture, detector and path and never hide verified findings',()=>{
 const target=new URL('https://example.com'); target.username='user'; target.password='secret';
 // Historical test fixture lacks the trailing slash generated by URL.
 const finding={DetectorName:'URI',Verified:false,Raw:target.href.replace(/\/$/,''),SourceMetadata:{Data:{Git:{file:'scripts/tests/short-links-db.test.ts'}}}};
 expect(isReviewedFalsePositive(finding)).toBe(true);
 expect(isReviewedFalsePositive({...finding,Verified:true})).toBe(false);
 expect(isReviewedFalsePositive({...finding,Raw:'different credential'})).toBe(false);
 expect(isReviewedFalsePositive({...finding,DetectorName:'Other'})).toBe(false);
 expect(isReviewedFalsePositive({...finding,SourceMetadata:{Data:{Git:{file:'other.ts'}}}})).toBe(false);
});
